local cam=workspace.CurrentCamera
local lp=game.Players.LocalPlayer
local hrp=lp.Character.HumanoidRootPart
local out={camType=tostring(cam.CameraType),camPos=tostring(cam.CFrame.Position),hrp=tostring(hrp.Position),d=(cam.CFrame.Position-hrp.Position).Magnitude,fov=cam.FieldOfView,subj=tostring(cam.CameraSubject)}
local scripts={}
for _,s in ipairs(lp.PlayerScripts:GetDescendants()) do if s:IsA('LocalScript') or s:IsA('ModuleScript') then table.insert(scripts,s.Name) end end
out.scripts=scripts
return game:GetService('HttpService'):JSONEncode(out)
